-- Seed: Indicadores de 2do de Secundaria - Ciencias Sociales

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('2do', 'Ciencias Sociales', 'BC1', 'IL-1', 'Identifica con pertinencia los movimientos sísmicos y sus puntos geográficos en distinto mapa, a partir de consulta en fuentes confiables de información.'),
('2do', 'Ciencias Sociales', 'BC1', 'IL-2', 'Elabora mapa de las migraciones humanas de una región o país, identificando los diferentes tipos de migraciones y las características de cada uno, utilizando informaciones confiables y rigurosa para garantizar la originalidad y autenticidad de la información recabada.'),
('2do', 'Ciencias Sociales', 'BC1', 'IL-3', 'Realiza en brochure e infografías, explicaciones sencillas de los cambios históricos, espaciales, políticos, económicos y culturales durante los períodos históricos estudiados.'),

-- BC2
('2do', 'Ciencias Sociales', 'BC2', 'IL-4', 'Analiza las tasas demográficas de un país, su evolución a lo largo del tiempo y evalúa la influencia de diferentes factores económicos o culturales presentes en estos cambios.'),
('2do', 'Ciencias Sociales', 'BC2', 'IL-5', 'Analiza los cambios que se produjeron en el mundo tras la Primera Guerra Mundial.'),
('2do', 'Ciencias Sociales', 'BC2', 'IL-6', 'Argumenta mediante ensayos e informes de lectura sobre las características fundamentales de la cultura moderna y postmoderna.'),
('2do', 'Ciencias Sociales', 'BC2', 'IL-7', 'Elabora proyectos comunitarios enfocados hacia la protección del medioambiente, aplicando conocimientos sobre los problemas ambientales y herramientas para su abordaje.'),
('2do', 'Ciencias Sociales', 'BC2', 'IL-8', 'Elabora una línea de tiempo que muestre los principales acontecimientos históricos del siglo estudiados.'),
('2do', 'Ciencias Sociales', 'BC2', 'IL-9', 'Aplica metodologías participativas y democráticas para buscar soluciones a conflictos en distintos contextos sociales.'),

-- BC3
('2do', 'Ciencias Sociales', 'BC3', 'IL-13', 'Compara las similitudes y diferencias entre los cambios ocurridos en el mundo durante el neocolonialismo, la descolonización y las guerras mundiales, utilizando varios mapas de fuentes confiables.'),
('2do', 'Ciencias Sociales', 'BC3', 'IL-14', 'Analiza teorías que explican la incidencia de las placas tectónicas en los continentes, las causas de sismos, terremotos, maremotos y huracanes.'),
('2do', 'Ciencias Sociales', 'BC3', 'IL-15', 'Explica mediante el análisis de autores relevantes, los tratados internacionales antes y después de las guerras mundiales y su impacto en la división del mundo en conceptos (norte y sur), así como en la percepción de la humanidad sobre estos.'),
('2do', 'Ciencias Sociales', 'BC3', 'IL-16', 'Desarrolla argumentos de manera funcional a través de textos que permitan comprender las propuestas presentadas por organismos internacionales en relación con la protección del medioambiente.'),
('2do', 'Ciencias Sociales', 'BC3', 'IL-17', 'Analiza la influencia de los factores naturales y humanos en los elementos del clima, sus implicaciones del calentamiento en el planeta Tierra a nivel global, regional y local, identificando sus causas y consecuencias.'),
('2do', 'Ciencias Sociales', 'BC3', 'IL-18', 'Analiza rigurosamente el impacto social de la incidencia de la contaminación en la República Dominicana, explorando las causas y consecuencias en la salud, economía, calidad de vida y medioambiente de la población afectada a nivel local y nacional.'),

-- BC4
('2do', 'Ciencias Sociales', 'BC4', 'IL-10', 'Elabora propuestas sobre prácticas democráticas, solución de conflictos y cultura de paz mediante la participación como medio de solución.'),
('2do', 'Ciencias Sociales', 'BC4', 'IL-11', 'Elabora proyectos sencillos sobre los aspectos fundamentales de la Constitución dominicana y las características del Estado de derecho.'),
('2do', 'Ciencias Sociales', 'BC4', 'IL-12', 'Elabora proyectos sobre educación vial y tributaria que permiten concientizar a la comunidad sobre la importancia del cumplimiento de las normas.'),
('2do', 'Ciencias Sociales', 'BC4', 'IL-19', 'Comprende la importancia del respeto a los derechos humanos y el respeto a lo establecido en la Constitución en la solución de problemáticas sociales.'),
('2do', 'Ciencias Sociales', 'BC4', 'IL-20', 'Realiza propuestas que garanticen la cultura de paz en cualquier espacio y el respeto a los derechos humanos.'),
('2do', 'Ciencias Sociales', 'BC4', 'IL-21', 'Propone proyectos comunitarios que benefician a todos los ciudadanos, utilizando herramientas y estrategias que fomenten la participación activa y colaborativa de la comunidad en la identificación de necesidades y soluciones.');
